begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
create function pg_temp.fi(t text) returns uuid language sql immutable as $$select md5('event-review-test-'||t)::uuid$$;
create function pg_temp.actor(t text) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.fi(t),'role','authenticated')::text,true)$$;
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) select pg_temp.fi(t),'00000000-0000-0000-0000-000000000000','authenticated','authenticated',t||'-family@example.invalid',case when t='unconfirmed' then null else now() end,now(),now() from unnest(array['owner','member','second','outside','unconfirmed'])t;
insert into public.organizations(id,name,slug,status) values(pg_temp.fi('org'),'Famílias fictícias','event-review-test','active'),(pg_temp.fi('outsideorg'),'Outro fictício','event-review-outside','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values(pg_temp.fi('a'),pg_temp.fi('org'),'Sede fictícia','a','headquarters'),(pg_temp.fi('b'),pg_temp.fi('org'),'Filial fictícia','b','campus');
insert into public.organization_memberships(id,organization_id,user_id,default_unit_id,role,status) select pg_temp.fi(t||'-membership'),pg_temp.fi('org'),pg_temp.fi(t),pg_temp.fi('a'),case when t='owner' then 'owner'::public.membership_role else 'member'::public.membership_role end,'active' from unnest(array['owner','member','second','unconfirmed'])t;
insert into public.people(id,organization_id,unit_id,auth_user_id,full_name,status,birth_date) select pg_temp.fi(t||'-person'),pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi(t),t||' pessoa fictícia','active',current_date-interval '35 years' from unnest(array['owner','member','second','unconfirmed'])t;
set local role authenticated;
select pg_temp.actor('owner');
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('account'),'kind','account','name','Banco fictício'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('income'),'kind','category','name','Receita fictícia','direction','income'));
select public.finance_f1(pg_temp.fi('org'),array[pg_temp.fi('a')],'catalog',jsonb_build_object('id',pg_temp.fi('expense'),'kind','category','name','Taxa fictícia','direction','expense'));
select public.finance_digital(pg_temp.fi('org'),pg_temp.fi('a'),'purpose',jsonb_build_object('id',pg_temp.fi('purpose'),'version',0,'name','Oferta fictícia','origin','event','account',pg_temp.fi('account'),'category',pg_temp.fi('income'),'feeCategory',pg_temp.fi('expense'),'refundCategory',pg_temp.fi('expense'),'creditCategory',pg_temp.fi('income'),'active',true));
reset role;
insert into private.finance_receivers(id,organization_id,unit_id,provider,environment,status,external_id,holder,holder_confirmed,beneficiary_units,account_id,created_by,expires_at,methods,payments_enabled,webhook_configured) values(pg_temp.fi('receiver'),pg_temp.fi('org'),pg_temp.fi('a'),'mercado_pago','production','configured','123','Conta fictícia',true,array[pg_temp.fi('a')],pg_temp.fi('account'),pg_temp.fi('owner'),now()+interval '1 day',array['pix'],true,true);
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select public.member_payment_publish(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('purpose'),pg_temp.fi('receiver'),true)$$,'publica finalidade com destino válido');

reset role;
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status) values(pg_temp.fi('event2'),pg_temp.fi('org'),pg_temp.fi('a'),'Tickets fictícios etapa 2','event',now()+interval '2 days',now()+interval '3 days',10,'published');
create function pg_temp.v() returns integer language sql security definer set search_path='' as $$select version from private.church_app_events where id=pg_temp.fi('event2')$$;
create function pg_temp.admin2(a text,i uuid default null,d jsonb default '{}') returns jsonb language sql as $$select public.event_ticket_admin(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),a,i,pg_temp.v(),d)$$;
create function pg_temp.settings2() returns jsonb language sql as $$select jsonb_build_object('enabled',true,'allow_guests',true,'show_remaining',true,'purpose',pg_temp.fi('purpose'),'receiving_unit',pg_temp.fi('a'),'reservation_hours',24,'questions','[]'::jsonb)$$;
create function pg_temp.type2(n text,mode text,price integer,quantity integer) returns jsonb language sql as $$select jsonb_build_object('name',n,'mode',mode,'price',price::text,'quantity',quantity::text,'starts',now()-interval '1 day','ends',now()+interval '1 day','active',true,'per_user','2','per_cpf','','audience','public','audience_units','[]'::jsonb,'position',0)$$;
create function pg_temp.payload2(t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select jsonb_build_object('buyerName','Pessoa fictícia','buyerEmail',buyer||'-family@example.invalid','emailConfirmation',buyer||'-family@example.invalid','coupon','','intent',intent,'items',jsonb_build_array(jsonb_build_object('type',pg_temp.fi(t),'name','Participante fictício','email','','cpf','','phone','','answers','{}'::jsonb)))$$;
create function pg_temp.buy2(id text,t text,buyer text default 'member',intent text default 'pay') returns jsonb language sql as $$select public.event_ticket_checkout(pg_temp.fi('event2'),'create',pg_temp.fi(id),case when buyer='guest' then null else pg_temp.fi(buyer) end,repeat('a',64),pg_temp.payload2(t,buyer,intent),repeat('f',64))$$;

set local role authenticated;select pg_temp.actor('owner');
select pg_temp.admin2('settings',null,pg_temp.settings2()||'{"allow_guests":false}');
select pg_temp.admin2('type',pg_temp.fi('free'),pg_temp.type2('Gratuito fictício','free',0,2));
select pg_temp.admin2('type',pg_temp.fi('paid'),pg_temp.type2('Pago fictício','paid',1000,3));
select pg_temp.admin2('type',pg_temp.fi('reserve'),pg_temp.type2('Reserva fictícia','reservation',1000,2));
reset role;
select is((select display_id::integer from private.church_app_events where id=pg_temp.fi('event2')),1,'primeiro evento do ministério recebe ID 1');
insert into private.church_app_events(id,organization_id,unit_id,title,kind,starts_at,ends_at,capacity,status,commerce_mode,pickup_at) values(pg_temp.fi('sale'),pg_temp.fi('org'),pg_temp.fi('a'),'Encomenda fictícia','event',now()+interval '3 days',now()+interval '3 days 2 hours',10,'draft','sale',now()+interval '1 day');
set constraints all immediate;
select is((select display_id::integer from private.church_app_events where id=pg_temp.fi('sale')),2,'segunda operação recebe ID 2');
select ok((select pickup_at<starts_at from private.church_app_events where id=pg_temp.fi('sale')),'retirada pode começar antes do fim dos pedidos');
select throws_ok($$update private.church_app_events set pickup_at=ends_at+interval '1 hour' where id=pg_temp.fi('sale')$$,'23514','invalid_commerce_pickup_end','retirada depois do prazo final recusada');
select throws_ok($$update private.church_app_events set display_id=99 where id=pg_temp.fi('sale')$$,'22023','event_number_immutable','ID publicado não é alterado');
set local role authenticated;select pg_temp.actor('owner');
select lives_ok($$select pg_temp.admin2('type',pg_temp.fi('unused'),pg_temp.type2('Item sem aquisição','free',0,1))$$,'cria item sem aquisições');
select lives_ok($$select pg_temp.admin2('type_delete',pg_temp.fi('unused'))$$,'exclui somente item sem histórico');
reset role;
select is((select count(*)::integer from private.event_ticket_types where id=pg_temp.fi('unused')),0,'item sem aquisição removido');
set local role service_role;
select pg_temp.buy2('review-paid','paid');
reset role;
set local role authenticated;select pg_temp.actor('owner');
select throws_ok($$select pg_temp.admin2('type_delete',pg_temp.fi('paid'))$$,'40001','event_ticket_has_orders','aquisição impede exclusão');
select throws_ok($$select pg_temp.admin2('type',pg_temp.fi('paid'),pg_temp.type2('Preço alterado','paid',2000,3))$$,'40001','event_ticket_has_orders','aquisição impede alterar definição');
select lives_ok($$select pg_temp.admin2('type_active',pg_temp.fi('paid'),'{"active":false}')$$,'item adquirido pode ser desativado');
select lives_ok($$select pg_temp.admin2('type_active',pg_temp.fi('paid'),'{"active":true}')$$,'item pode ser reativado');
select is(public.event_checkout_review(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),pg_temp.fi('review-paid'))->>'gross','1000','conferência usa valor do pedido salvo');
select throws_ok($$select public.event_checkout_review(pg_temp.fi('org'),pg_temp.fi('b'),pg_temp.fi('event2'),pg_temp.fi('review-paid'))$$,'42501','event_review_denied','outra igreja não confere pedido');
select pg_temp.actor('member');
select throws_ok($$select public.event_checkout_review(pg_temp.fi('org'),pg_temp.fi('a'),pg_temp.fi('event2'),pg_temp.fi('review-paid'))$$,'42501','event_review_denied','membro não recebe dados de conferência financeira');
reset role;
update private.event_ticket_orders set checkout_state='dispatching' where id=pg_temp.fi('review-paid');
set local role service_role;
select lives_ok($$select public.event_ticket_delivery(pg_temp.fi('review-paid'),'not_sent','{}')$$,'recusa confirmada libera somente tentativa sem envio confirmado');
reset role;
select is((select checkout_state from private.event_ticket_orders where id=pg_temp.fi('review-paid')),'reserved','recusa confirmada não retém estado ambíguo');
update private.event_ticket_orders set checkout_state='uncertain' where id=pg_temp.fi('review-paid');
set local role service_role;
select lives_ok($$select public.event_ticket_delivery(pg_temp.fi('review-paid'),'complete','{"preference":"verified-existing","url":"https://www.mercadopago.com.br/checkout/v1/redirect?pref_id=verified-existing"}')$$,'servidor registra preferência existente sem criar outra');
reset role;
select is((select state from private.event_ticket_orders where id=pg_temp.fi('review-paid')),'holding','recuperar link não confirma pagamento');
select is((select count(*)::integer from private.finance_digital_receipts where order_id=pg_temp.fi('review-paid')),0,'link recuperado não inventa recebimento');
select ok(not has_function_privilege('authenticated','public.event_ticket_delivery(uuid,text,jsonb)','execute'),'cliente não pode forjar link externo');
set local role authenticated;select pg_temp.actor('owner');
select is(jsonb_array_length(public.event_information_admin(pg_temp.fi('org'),pg_temp.fi('a'),'choices')->'users'),3,'busca oferece membros vinculados com conta confirmada');
reset role;
update public.people set auth_user_id=null where id=pg_temp.fi('member-person');
set local role authenticated;select pg_temp.actor('owner');
select is(jsonb_array_length(public.event_information_admin(pg_temp.fi('org'),pg_temp.fi('a'),'choices')->'users'),2,'conta sem vínculo aprovado não aparece na busca');
reset role;
insert into public.people(id,organization_id,unit_id,full_name,email,cpf,status) values(pg_temp.fi('candidate'),pg_temp.fi('org'),pg_temp.fi('a'),'Membro fictício para comparação','different@example.invalid','529.982.247-25','active');
set local role authenticated;select pg_temp.actor('outside');
select lives_ok($$select public.member_self_service(pg_temp.fi('org'),'submit',pg_temp.fi('a'),'{"full_name":"Cadastro fictício pendente","cpf":"52998224725"}')$$,'cadastro do aplicativo encaminhado à administração');
select is(public.member_self_service(pg_temp.fi('org'),'profile')->>'membershipStatus','pending','revisão pendente preserva conta sem conceder papel administrativo');
reset role;set local role anon;
select ok(public.member_app_config('event-review-test') is not null,'conteúdo público do aplicativo segue acessível durante revisão');
reset role;
reset role;
select is((select person_id::text from private.member_profile_requests where user_id=pg_temp.fi('outside')),pg_temp.fi('candidate')::text,'CPF formatado encontra membro existente sem duplicar cadastro');
select is((select auth_user_id from public.people where id=pg_temp.fi('candidate')),null::uuid,'correspondência não vincula conta antes da aprovação');
set local role authenticated;select pg_temp.actor('owner');
select is((public.member_profile_review(pg_temp.fi('org'),'list')->'items'->0->'identity_match'->>'cpf')::boolean,true,'administração recebe análise da correspondência por CPF');
reset role;
select finish();rollback;
